#!/usr/bin/env python3
"""Write attendees_clean.csv with only each email's first occurrence."""

import csv

INPUT_FILE = "attendees.csv"
OUTPUT_FILE = "attendees_clean.csv"


def main():
    with open(INPUT_FILE, "r", encoding="utf-8", newline="") as source, open(
        OUTPUT_FILE, "w", encoding="utf-8", newline=""
    ) as destination:
        reader = csv.reader(source)
        writer = csv.writer(destination, lineterminator="\n")

        header = next(reader, None)
        if header is None:
            return
        writer.writerow(header)

        try:
            email_column = header.index("email")
        except ValueError:
            raise ValueError("attendees.csv must contain an email column")

        seen_emails = set()
        for row in reader:
            # Rows with too few fields cannot provide an email, so retain them.
            if len(row) <= email_column or row[email_column] not in seen_emails:
                writer.writerow(row)
                if len(row) > email_column:
                    seen_emails.add(row[email_column])


if __name__ == "__main__":
    main()
